const precos = [10, 25, 40];

// forEach: efeito secundário, sem retorno útil
precos.forEach(preco => console.log(`Preço: ${preco}€`));

// map: novo array com os preços com IVA incluído
const precosComIva = precos.map(preco => Math.round(preco * 1.23 * 100) / 100);

console.log(precosComIva); // [12.3, 30.75, 49.2]
console.log(precos); // [10, 25, 40] — original inalterado

const produtos = [
  { nome: 'Teclado', preco: 45, stock: 12 },
  { nome: 'Rato', preco: 15, stock: 0 },
  { nome: 'Monitor', preco: 220, stock: 3 },
];

const disponiveis = produtos.filter(produto => produto.stock > 0);
console.log(disponiveis.map(p => p.nome)); // ['Teclado', 'Monitor']

// o predicado recebe também o índice
const primeirosDoisCaros = produtos.filter((produto, indice) => produto.preco > 40 && indice < 2);
console.log(primeirosDoisCaros.map(p => p.nome)); // ['Teclado']

const vendas = [
  { categoria: 'Livros', valor: 20 },
  { categoria: 'Livros', valor: 15 },
  { categoria: 'Música', valor: 30 },
];

// soma simples, com valor inicial explícito
const totalVendas = vendas.reduce((acumulador, venda) => acumulador + venda.valor, 0);
console.log(totalVendas); // 65

// agrupamento por categoria
const totalPorCategoria = vendas.reduce((acumulador, venda) => {
  acumulador[venda.categoria] = (acumulador[venda.categoria] ?? 0) + venda.valor;
  return acumulador;
}, {});
console.log(totalPorCategoria); // { Livros: 35, Música: 30 }

const utilizadores = [
  { id: 1, nome: 'Ana', ativo: true },
  { id: 2, nome: 'Bruno', ativo: false },
  { id: 3, nome: 'Carla', ativo: true },
];

const primeiroAtivo = utilizadores.find(u => u.ativo);
console.log(primeiroAtivo?.nome); // 'Ana'

const indiceInativo = utilizadores.findIndex(u => !u.ativo);
console.log(indiceInativo); // 1

const ultimoAtivo = utilizadores.findLast(u => u.ativo);
console.log(ultimoAtivo?.nome); // 'Carla'

const notas = [14, 16, 9, 18];

const temNegativa = notas.some(nota => nota < 10);
console.log(temNegativa); // true

const todasPositivas = notas.every(nota => nota >= 0);
console.log(todasPositivas); // true

const todasAprovadas = notas.every(nota => nota >= 10);
console.log(todasAprovadas); // false

const turmas = [[1, 2], [3, 4], [5]];
console.log(turmas.flat()); // [1, 2, 3, 4, 5]

const matriz = [[1, [2, 3]], [4, [5, 6]]];
console.log(matriz.flat(2)); // [1, 2, 3, 4, 5, 6]

const frases = ['bom dia', 'boa tarde'];
const palavras = frases.flatMap(frase => frase.split(' '));
console.log(palavras); // ['bom', 'dia', 'boa', 'tarde']

// flatMap também serve para "filtrar" devolvendo array vazio
const pares = [1, 2, 3, 4].flatMap(n => (n % 2 === 0 ? [n] : []));
console.log(pares); // [2, 4]

