function aplicarDesconto(precos) {
  return precos.map(preco => Math.round(preco * 0.9 * 100) / 100);
}

const precos = [50, 120, 15, 200, 8];
console.log(aplicarDesconto(precos)); // [45, 108, 13.5, 180, 7.2]
console.log(precos); // [50, 120, 15, 200, 8] — inalterado

function relatorioInscricoes(participantes) {
  const menoresDeIdade = participantes
    .filter(participante => participante.idade < 18)
    .map(participante => participante.nome);

  const todosPagaram = participantes.every(participante => participante.pagou);

  const pendente = participantes.find(participante => !participante.pagou);

  return {
    menoresDeIdade,
    todosPagaram,
    primeiroPendente: pendente ? pendente.nome : null,
  };
}

const participantes = [
  { nome: 'Ana', idade: 17, pagou: true },
  { nome: 'Bruno', idade: 22, pagou: true },
  { nome: 'Carla', idade: 19, pagou: false },
];

console.log(relatorioInscricoes(participantes));
// { menoresDeIdade: ['Ana'], todosPagaram: false, primeiroPendente: 'Carla' }

function mediaEncomendasPagas(encomendas) {
  const totaisPagos = encomendas
    .filter(encomenda => encomenda.paga)
    .map(encomenda => encomenda.total);

  if (totaisPagos.length === 0) return 0;

  const soma = totaisPagos.reduce((acumulador, total) => acumulador + total, 0);
  return Math.round((soma / totaisPagos.length) * 100) / 100;
}

const encomendas = [
  { cliente: 'Ana', total: 120, paga: true },
  { cliente: 'Bruno', total: 45, paga: false },
  { cliente: 'Carla', total: 300, paga: true },
  { cliente: 'Duarte', total: 80, paga: true },
];

console.log(mediaEncomendasPagas(encomendas)); // 166.67

function totalPorVendedor(vendas) {
  const itensComVendedor = vendas.flatMap(venda =>
    venda.itens.map(item => ({ vendedor: venda.vendedor, ...item }))
  );

  return itensComVendedor.reduce((totais, item) => {
    const valorItem = item.quantidade * item.precoUnitario;
    totais[item.vendedor] = (totais[item.vendedor] ?? 0) + valorItem;
    return totais;
  }, {});
}

const vendas = [
  {
    vendedor: 'Ana',
    itens: [
      { produto: 'Livro', quantidade: 2, precoUnitario: 10 },
      { produto: 'Caneta', quantidade: 5, precoUnitario: 1 },
    ],
  },
  { vendedor: 'Bruno', itens: [{ produto: 'Livro', quantidade: 1, precoUnitario: 10 }] },
  { vendedor: 'Ana', itens: [{ produto: 'Caderno', quantidade: 3, precoUnitario: 4 }] },
];

console.log(totalPorVendedor(vendas));
// { Ana: 37, Bruno: 10 }
